def first_Repeated_Char(s):
    seen_chars = set()
    for char in s:
        if char in seen_chars:
            return char
        seen_chars.add(char)
    return None

# Example usage:
input_str = "programming"
print(f"The first repeated character in '{input_str}' is: {first_Repeated_Char(input_str)}")

def find_Min(arr, low, high):
    # Base case: if the array is not rotated
    if high < low:
        return arr[0]

    # Base case: if the array is of length 1
    if low == high:
        return arr[low]

    # Find the middle element
    mid = low + (high - low) // 2

    # If the middle element is smaller than the next element,
    # then the minimum is in the left half
    if arr[mid] < arr[high]:
        return find_Min(arr, low, mid)

    # Else, the minimum is in the right half
    return find_Min(arr, mid + 1, high)

# Example usage:
arr = [4, 5, 6, 7, 0, 1, 2]
low = 0
high = len(arr) - 1
print("The minimum element is:", find_Min(arr, low, high))

